insert into public.ace_quizzes(title,course_code,description) select 'Business Law · Contract Basics','BFB3201','Introductory general contract principles; compare local legal requirements with Kenyan law.' where not exists(select 1 from public.ace_quizzes where title='Business Law · Contract Basics');with z as (select id from public.ace_quizzes where title='Business Law · Contract Basics' limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select z.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from z cross join(values ('In a typical common-law contract analysis, an agreement is most clearly formed through:','["An offer and matching acceptance","An unsigned advertising slogan","A casual prediction about prices","A company logo"]',0,'Offer and acceptance are core concepts used to identify contractual agreement.',1),('Consideration in a common-law bargain generally refers to:','["An exchange of something of value","The number of witnesses at an event","Only a printed letterhead","A promise that no one relies on"]',0,'Consideration refers to something of value exchanged in a bargain, which can include goods, services or promises.',2),('A person appointed to negotiate a contract on behalf of a business usually acts as:','["An agent of the principal","A supplier of dividends","The regulator of the industry","An unrelated shareholder"]',0,'In agency relationships, a person may act with delegated authority on behalf of a principal.',3),('A breach of contract generally describes:','["Failure to perform a contractual duty without legal excuse","All disagreements between employees","An ordinary change in a company''s logo","The filing of annual accounts"]',0,'Breach involves the unjustified non-performance of a contractual obligation.',4),('Which first step most helps a business avoid misunderstanding when making an agreement?','["Clarifying scope, price and responsibilities in writing","Avoiding all written records","Relying on assumptions without discussing them","Changing terms silently after acceptance"]',0,'Clear, documented terms reduce ambiguity and help parties understand their obligations.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;insert into public.ace_quizzes(title,course_code,description) select 'Public Relations · Practical Communication','BFB3205','Audience analysis, earned media, stakeholder relationships and crisis response.' where not exists(select 1 from public.ace_quizzes where title='Public Relations · Practical Communication');with z as (select id from public.ace_quizzes where title='Public Relations · Practical Communication' limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select z.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from z cross join(values ('Before selecting a communication channel, a PR team should first:','["Identify the target stakeholders and objectives","Choose a logo without research","Publish every message to everyone","Measure only social followers"]',0,'Identifying stakeholders and objectives helps the team select relevant messages and channels.',1),('A newspaper covers a student-led charity event without a paid advertising placement. This is an example of:','["Earned media","Paid search advertising","A private staff memorandum","Inventory valuation"]',0,'Earned coverage arises through independent editorial or public attention rather than directly purchasing placement.',2),('During an organizational crisis, the most constructive initial communication is:','["Timely, fact-checked information with acknowledgement of uncertainty","Speculation presented as certain fact","Silence regardless of risk to the public","Blaming audiences before checking evidence"]',0,'Accurate and timely updates support trust, while admitting unknowns avoids misleading people.',3),('A university student association wants to improve trust with its members. Which approach is strongest?','["Two-way feedback and follow-through on concerns","Only broadcasting promotional posters","Deleting all critical comments without review","Making promises without updates"]',0,'Constructive public relations involves listening and responsiveness, not only broadcasting messages.',4),('Which measurement best demonstrates that a safety awareness campaign worked?','["A measured improvement in understanding and safer behavior","The number of different poster colors","The personal preference of one designer","The cost of the meeting room alone"]',0,'Outcomes such as comprehension and behavior change are stronger evidence of impact than production details.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;